const reveals=document.querySelectorAll('.intro, .service, .steps article, .reasons>div, .plans article, .faq-grid, .contact-grid, .difference h2, .motion, .world-preview');if(!reduce.matches){const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});reveals.forEach(e=>{e.classList.add('reveal');observer.observe(e)})}
let ticking=false;const progress=document.querySelector('.scroll-progress');addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;progress.style.width=(total?scrollY/total*100:0)+'%';ticking=false})}},{passive:true});const glow=document.querySelector('.cursor-glow');if(matchMedia('(pointer:fine)').matches)addEventListener('pointermove',e=>{glow.style.transform=`translate(${e.clientX-200}px,${e.clientY-200}px)`},{passive:true});
const gallery=document.querySelector('#world-preview'),buttons=[...document.querySelectorAll('[data-world]')],slides=[...gallery.querySelectorAll('.gallery-slide')],status=document.querySelector('#gallery-status');let active=0,scrollFrame=0;const names=['Creative studio','Coffee culture','Concept store'];
function sync(index){active=index;buttons.forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-pressed',String(i===index));b.setAttribute('aria-controls',slides[i].id)});status.textContent=`0${index+1} / 03 · ${names[index]}`}
