buttons.forEach((b,i)=>b.addEventListener('click',()=>go(i)));gallery.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;sync(Math.max(0,Math.min(2,Math.round(gallery.scrollLeft/gallery.clientWidth))))})},{passive:true});gallery.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(active+(e.key==='ArrowRight'?1:-1))}});let previousWidth=gallery.clientWidth;new ResizeObserver(()=>{if(gallery.clientWidth!==previousWidth){previousWidth=gallery.clientWidth;gallery.scrollTo({left:active*previousWidth,behavior:'instant'})}}).observe(gallery);sync(0);
